import audioop
import wave
from dataclasses import asdict, dataclass
from typing import Dict, Optional, Type, TypeVar

import structlog

from rasa.core.channels.voice_stream.audio_bytes import (
    MULAW_8KHZ,
    AudioEncoding,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.shared.exceptions import RasaException

structlogger = structlog.get_logger()

# G.711 μ-law encodes a zero-amplitude sample as 0xFF; 0x00 is the loudest
# negative sample, so zero-filled "silence" is audible as clicks on Twilio.
_SILENCE_BYTE_BY_ENCODING: Dict[AudioEncoding, bytes] = {
    AudioEncoding.LINEAR: b"\x00",
    AudioEncoding.MULAW: b"\xff",
}


def read_wav_to_rasa_audio_bytes(file_name: str) -> Optional[RasaAudioBytes]:
    """Reads rasa audio bytes from a file."""
    if not file_name.endswith(".wav"):
        raise RasaException("Should only read .wav files with this method.")
    wave_object = wave.open(file_name, "rb")
    wave_data = wave_object.readframes(wave_object.getnframes())
    if wave_object.getnchannels() != 1:
        wave_data = audioop.tomono(wave_data, wave_object.getsampwidth(), 1, 1)
    if wave_object.getsampwidth() != 1:
        wave_data = audioop.lin2lin(wave_data, wave_object.getsampwidth(), 1)
        # 8 bit is unsigned
        # wave_data = audioop.bias(wave_data, 1, 128)
    if wave_object.getframerate() != MULAW_8KHZ.sample_rate:
        wave_data, _ = audioop.ratecv(
            wave_data, 1, 1, wave_object.getframerate(), MULAW_8KHZ.sample_rate, None
        )
    wave_data = audioop.lin2ulaw(wave_data, 1)
    return RasaAudioBytes(wave_data, format=MULAW_8KHZ)


def generate_silence(
    format: AudioFormat, length_in_seconds: float = 1.0
) -> RasaAudioBytes:
    """Generate silent audio for the given format and duration.

    The byte pattern that represents silence depends on the encoding: linear PCM
    uses zero samples, while μ-law uses ``0xFF``.

    Args:
        format: Target audio format; its encoding selects the silence byte pattern.
        length_in_seconds: Duration of the generated silence.

    Returns:
        Silent audio in the requested format.

    Raises:
        ValueError: If the format's encoding has no known silence representation.
    """
    silence_byte = _SILENCE_BYTE_BY_ENCODING.get(format.encoding)
    if silence_byte is None:
        raise ValueError(
            f"Cannot generate silence for unsupported audio encoding: "
            f"{format.encoding}"
        )
    num_bytes = int(length_in_seconds * format.bytes_per_second)
    return RasaAudioBytes(silence_byte * num_bytes, format=format)


T = TypeVar("T", bound="MergeableConfig")


@dataclass
class MergeableConfig:
    def __init__(self) -> None:
        pass

    def merge(self: T, other: Optional[T]) -> T:
        """Merges two configs while dropping None values of the second config."""
        if other is None:
            return self
        other_dict = asdict(other)
        other_dict_clean = {k: v for k, v in other_dict.items() if v is not None}
        merged = {**asdict(self), **other_dict_clean}
        return self.from_dict(merged)

    @classmethod
    def from_dict(cls: Type[T], data: dict[str, Optional[str]]) -> T:
        return cls(**data)


def repack_voice_credentials(
    credentials: Dict[str, str],
) -> Dict[str, str]:
    """Repack voice credentials to ensure they are in the correct format."""
    new_creds = {**credentials}
    new_creds["asr_config"] = new_creds.pop("asr", None)
    new_creds["tts_config"] = new_creds.pop("tts", None)
    return new_creds
